{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE ftune-wh.maplemonk.ftune_wh_AD_PERFORMANCE AS WITH shopify AS ( SELECT DATE(order_timestamp) AS date, CAST(final_utm_campaign AS STRING) AS campaign_id, CAST(final_utm_term AS STRING) AS adset_id, CAST(final_utm_content AS STRING) AS ad_id, COUNT(DISTINCT order_id) AS orders, SUM(total_sales) AS revenue, COUNT(DISTINCT CASE WHEN SHOPIFY_NEW_CUSTOMER_FLAG = \'NEW\' THEN order_id END) AS new_customer_orders, SUM(CASE WHEN SHOPIFY_NEW_CUSTOMER_FLAG = \'NEW\' THEN total_sales END) AS new_customer_revenue FROM ftune-wh.maplemonk.ftune_wh_SHOPIFY_FACT_ITEMS WHERE final_utm_campaign IS NOT NULL GROUP BY 1,2,3,4 ), marketing AS ( SELECT DATE, CAST(CAMPAIGN_ID AS STRING) AS campaign_id, CAST(ADSET_ID AS STRING) AS adset_id, CAST(AD_ID AS STRING) AS ad_id, CAMPAIGN_NAME, ADSET_NAME, AD_NAME, SUM(SPEND) AS spend, SUM(CLICKS) AS clicks, SUM(IMPRESSIONS) AS impressions, status, effective_status FROM ftune-wh.maplemonk.ftune_wh_MARKETING_CONSOLIDATED where lower(channel) like \'%facebook%\' GROUP BY 1,2,3,4,5,6,7, status, effective_status ), historical_ads AS ( SELECT DISTINCT CAST(AD_ID AS STRING) AS ad_id, ANY_VALUE(CAMPAIGN_ID) AS campaign_id, ANY_VALUE(ADSET_ID) AS adset_id, ANY_VALUE(CAMPAIGN_NAME) AS campaign_name, ANY_VALUE(ADSET_NAME) AS adset_name, ANY_VALUE(AD_NAME) AS ad_name FROM ftune-wh.maplemonk.ftune_wh_MARKETING_CONSOLIDATED where lower(channel) like \'%facebook%\' GROUP BY 1 ) SELECT COALESCE(s.DATE, m.date) AS date, COALESCE(s.campaign_id, m.campaign_id, h.campaign_id) AS campaign_id, COALESCE(s.adset_id, m.adset_id, h.adset_id) AS adset_id, COALESCE(s.ad_id, m.ad_id, h.ad_id) AS ad_id, COALESCE(m.CAMPAIGN_NAME, h.CAMPAIGN_NAME) as CAMPAIGN_NAME, COALESCE(m.ADSET_NAME, h.ADSET_NAME) as ADSET_NAME, COALESCE(m.AD_NAME, h.AD_NAME) as AD_NAME, m.spend, m.clicks, m.impressions, m.status, m.effective_status, IFNULL(s.orders, 0) AS shopify_attributed_orders, IFNULL(s.revenue, 0) AS shopify_attributed_revenue, IFNULL(s.new_customer_orders, 0) AS new_customer_orders, IFNULL(s.new_customer_revenue, 0) AS new_customer_revenue, SAFE_DIVIDE(IFNULL(s.revenue,0), m.spend) AS shopify_attributed_roas, SAFE_DIVIDE(m.spend, IFNULL(s.orders, 0)) AS cpa, SAFE_DIVIDE(s.revenue, IFNULL(s.orders, 0)) AS aov, SAFE_DIVIDE(IFNULL(s.orders, 0), m.clicks) AS conversion_rate, SAFE_DIVIDE(s.new_customer_revenue, m.spend) AS new_customer_roas, CASE WHEN m.ad_id IS NOT NULL THEN \'Exact Match\' WHEN m.ad_id IS NULL AND h.ad_id IS NOT NULL THEN \'Recovered (Historical)\' ELSE \'Unmatched\' END AS match_type, CASE WHEN m.effective_status = \'ACTIVE\' THEN \'Active\' WHEN m.effective_status = \'PAUSED\' THEN \'Paused\' WHEN m.effective_status = \'ADSET_PAUSED\' THEN \'Paused (Adset)\' WHEN m.effective_status = \'CAMPAIGN_PAUSED\' THEN \'Paused (Campaign)\' WHEN m.effective_status IS NULL AND h.ad_id IS NOT NULL THEN \'No Meta Data (Recovered)\' WHEN m.effective_status IS NULL THEN \'No Meta Data\' ELSE m.effective_status END AS ad_status, CASE WHEN m.effective_status = \'ACTIVE\' THEN \'Active\' WHEN m.effective_status != \'ACTIVE\' AND (IFNULL(s.orders, 0) > 0 OR IFNULL(s.revenue, 0) > 0) THEN \'Inactive but Has Orders\' WHEN m.effective_status IS NULL AND h.ad_id IS NOT NULL THEN \'Recovered Order\' ELSE \'Other\' END AS performance_status FROM shopify s LEFT JOIN marketing m ON m.DATE = s.date AND m.CAMPAIGN_ID = s.campaign_id AND m.ADSET_ID = s.adset_id AND m.AD_ID = s.ad_id LEFT JOIN historical_ads h ON s.ad_id = h.ad_id AND m.ad_id IS NULL WHERE ( m.effective_status = \'ACTIVE\' ) OR ( m.effective_status != \'ACTIVE\' AND (IFNULL(s.orders, 0) > 0 OR IFNULL(s.revenue, 0) > 0) ) OR ( m.ad_id IS NULL AND h.ad_id IS NOT NULL );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            